{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0002",
          "reason": "Current legal-status page; useful for treaty baseline, but not a 2022 contemporaneous ruler action."
        },
        {
          "evidence_id": "E0004",
          "reason": "Current CTBT status page; treat as background on Egypt's formal status, not as direct 2022 conduct."
        },
        {
          "evidence_id": "E0015",
          "reason": "Inherited-baseline context only; it should not be read as evidence of Sisi's own 2022 nuclear-risk choices."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 ruler-level nuclear safety, command-and-control, and safeguards decisions are thin; most evidence is treaty status, civilian Dabaa licensing, and diplomacy.",
          "lenses": ["1B.3", "1B.4", "1B.7", "1B.8", "1B.9"],
          "best_source_or_query_direction": "Primary IAEA/ENRRA records, CTBTO/UNODA treaty-implementation files, and any 2022 cabinet or presidential security directives tied to the nuclear program.",
          "why_it_matters": "Without a direct choice, the chapter stays a limited-exposure case and should not be overread as demonstrated restraint or risk-taking."
        }
      ],
      "reason": "The package fairly shows Egypt's civilian nuclear posture, treaty baseline, and disarmament rhetoric, but most of it is contextual rather than a 2022 ruler-level safety or command choice."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Behind-the-scenes mediation leverage is less directly evidenced than the public diplomacy record.",
          "lenses": ["2B.1", "2B.7", "2B.10"],
          "best_source_or_query_direction": "Contemporaneous mediator notes, foreign-ministry chronologies, UN coordination records, or Reuters-style reporting on the Gaza, Libya, and Turkey channels.",
          "why_it_matters": "It would tighten attribution for the de-escalation record without changing the broad finding that 2022 was mediation-heavy rather than war-making."
        }
      ],
      "reason": "The package fairly presents Egypt's limited-exposure status together with genuine 2022 de-escalatory diplomacy in Gaza, Ukraine, Libya, and Turkey, while also preserving the fact that those efforts did not resolve the underlying conflicts."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Exact command chains and undercounting of disappearances, torture, and protest detentions remain opaque.",
          "lenses": ["3B.1", "3B.2", "3B.4", "3B.10"],
          "best_source_or_query_direction": "UN mechanisms, domestic court files, incident-level rights datasets, and corroborated local testimony tied to named detention and abuse cases.",
          "why_it_matters": "It would sharpen attribution and severity while leaving the overall severity reading intact."
        }
      ],
      "reason": "The package fairly presents severe domestic repression, weak accountability, and limited remedial steps, with clear contrary evidence and reasonable attribution caveats."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "There was no 2022 election or transfer stress test, so dialogue and media controls are doing most of the work as proxies for contestability.",
          "lenses": ["4B.1", "4B.2", "4B.8", "4B.10"],
          "best_source_or_query_direction": "Election-administration records, party-registration materials, court rulings, and succession/term-limit documentation from 2022 and adjacent years.",
          "why_it_matters": "It would strengthen the contestability assessment rather than relying mainly on dialogue, press, and protest restrictions."
        }
      ],
      "reason": "The package fairly presents authoritarian control together with a constrained national-dialogue and pardon narrative, and it balances official claims against independent criticism of press, digital, and opposition restrictions."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Implementation and household-distribution effects of the announced reforms are thinner than the crisis-response record.",
          "lenses": ["5B.2", "5B.4", "5B.6", "5B.10"],
          "best_source_or_query_direction": "Budget-execution data, IMF review documents, enterprise/private-sector indicators, and household or labor-market distribution series for 2022-2023.",
          "why_it_matters": "It would separate real policy execution from crisis-management signaling and help judge durability."
        }
      ],
      "reason": "The package fairly presents crisis management, IMF-backed adjustment, devaluation, inflation, and state/private-sector reform claims, while also showing that 2022 was largely a shock-response year rather than a durable welfare surge."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Hard 2022 household microdata on nutrition, learning, and regional service quality remain thin.",
          "lenses": ["6B.2", "6B.3", "6B.8", "6B.10"],
          "best_source_or_query_direction": "Household surveys, DHS-style microdata, administrative service-delivery records, and independent program evaluations with regional breakdowns.",
          "why_it_matters": "It would test whether the visible program expansion translated into actual life-chance gains rather than just budgeted intent."
        }
      ],
      "reason": "The package fairly presents social-protection expansion and some service-delivery efforts alongside inflation, poverty risk, and incomplete outcome attribution."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0025",
          "reason": "Country-level repression baseline; useful context, but not evidence of Sisi's personal honesty, conflicts, or self-enrichment."
        },
        {
          "evidence_id": "E0059",
          "reason": "Structural military-economy analysis; it shows capture and opacity, but not a forensic finding of Sisi's direct personal enrichment."
        },
        {
          "evidence_id": "E0060",
          "reason": "Retrospective investment-climate baseline; context only, not ruler-specific integrity evidence."
        },
        {
          "evidence_id": "E0077",
          "reason": "IMF staff-level agreement is an official policy commitment, not proof of candor, correction, or separation of interests."
        },
        {
          "evidence_id": "E0078",
          "reason": "IMF board approval is program context, not evidence of Sisi's personal truthfulness or integrity."
        },
        {
          "evidence_id": "E0079",
          "reason": "State-ownership policy is a formal pledge; it should not be treated as delivery or ethical restraint."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 evidence of personal truthfulness, asset/conflict disclosures, procurement or beneficial-ownership records, and forensic accountability findings is missing.",
          "lenses": ["7B.1", "7B.3", "7B.4", "7B.5", "7B.6"],
          "best_source_or_query_direction": "Primary financial disclosures, procurement and beneficial-ownership records, audit or inquiry reports, court findings, and direct speech-versus-fact comparisons.",
          "why_it_matters": "Without a personal nexus, the chapter risks conflating authoritarian repression and structural state capture with Sisi's own integrity."
        }
      ],
      "reason": "The package is not yet strong enough for a fair personal-integrity judgment: it relies heavily on country-level repression and structural state-capital context, but lacks direct evidence of personal truthfulness, enrichment, conflicts, or forensic accountability findings."
    },
    {
      "chapter_id": "8B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0091",
          "reason": "Structural military-economy context; it is useful background, but not direct 2022 execution evidence."
        },
        {
          "evidence_id": "E0092",
          "reason": "Rights-monitor summary of repression; useful as context on control and reform limits, but not direct proof of economic or administrative competence."
        }
      ],
      "material_gaps": [
        {
          "gap": "The explicit program portfolio and end-state progress are only partly evidenced; several items are commitments or context rather than implementation proof.",
          "lenses": ["8B.1", "8B.7", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Presidential directives, budget-execution records, implementation reviews, and independent outcome data for the state-ownership, IMF, and social-policy tracks.",
          "why_it_matters": "It would separate declared goals from actual execution and make the competence judgment more defensible."
        }
      ],
      "reason": "The package fairly shows a mixed execution record for Sisi's stated economic and governance program, but the explicit program portfolio, implementation chain, and durable end-state progress remain only partly evidenced."
    }
  ]
}
